script:
(function () {
  'use strict';
  // Payroll FSA: per-paycheck deduction and the real change in take-home pay.
  // Taxes are figured for the whole 2026 year with and without the FSA elections, then:
  //   FSA deduction per paycheck = (health election + dependent care election) / paychecks used
  //   tax saved per paycheck     = (annual tax without - annual tax with) / paychecks used
  //   take-home drop             = deduction - tax saved
  // Annual taxes (an estimate of liability, not the IRS Pub. 15-T withholding tables):
  //   FICA wages    = salary - pre-tax premiums - FSA elections (401(k) stays FICA-taxable)
  //   federal wages = FICA wages - 401(k); taxable = federal wages - standard deduction
  //   federal tax   = brackets - child tax credit (not below zero; no 65+ deductions)
  //   state tax     = flat rate x federal wages
  // CHECKS (Node, scratch tests): single, $60,000, biweekly, $2,000 health FSA, 5% state:
  // federal $5,020 -> $4,780 (taxable $43,900 -> $41,900, 12% bracket), Social Security $124,
  // Medicare $29, state $100 -> $493 a year saved, $76.92 deducted and $18.96 saved per
  // paycheck, take-home down $57.96; spread over 13 paychecks -> $153.85 deducted, $37.92 saved;
  // MFJ $100,000 with $5,000 dependent care -> taxable $67,800 -> $62,800, federal saved $600;
  // salary $185,000 -> Social Security saved only on the $1,500 below the $184,500 wage base ($702 total); elections are
  // capped at $3,400 health and $7,500 dependent care ($3,750 married filing separately).
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Brackets and standard deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21).
  // Child tax credit $2,200 and $200,000 / $400,000 phase-out: IRC 24(h) as amended by P.L. 119-21.
  // Health FSA salary reduction limit $3,400: Rev. Proc. 2025-32 sec. 3.15 (IRC 125(i)).
  // Dependent care assistance $7,500 ($3,750 married filing separately): IRC 129(a)(2) as amended
  // by P.L. 119-21, for tax years beginning after 2025 (IRS Pub. 15-B, 2026).
  // Social Security wage base $184,500 and rates: SSA 2026 COLA fact sheet; Medicare IRC 3101(b).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var CHILD_CREDIT = 2200;
  var CREDIT_PHASEOUT_START = { single: 200000, hoh: 200000, mfs: 200000, mfj: 400000 }; // $50 per $1,000
  var SS_RATE = 0.062, SS_WAGE_BASE = 184500;
  var MEDICARE_RATE = 0.0145, ADDL_MEDICARE_RATE = 0.009, ADDL_MEDICARE_START = 200000;
  var HEALTH_FSA_LIMIT = 3400;
  var DC_FSA_LIMIT = { single: 7500, mfj: 7500, hoh: 7500, mfs: 3750 };
  // ---------------------------------------------------------------------------------------

  function bracketTax(taxable, limits) {
    var tax = 0, lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (taxable > lower) tax += (Math.min(taxable, upper) - lower) * RATES[i];
      lower = upper;
    }
    return tax;
  }

  // o: salary, status, k401 (annual $), premiums (annual $), fsa (annual $), kids, state (decimal)
  function taxes(o) {
    var ficaWages = Math.max(0, o.salary - o.premiums - o.fsa);
    var fedWages = Math.max(0, ficaWages - o.k401);
    var taxable = Math.max(0, fedWages - STANDARD_DEDUCTION[o.status]);
    var credits = o.kids * CHILD_CREDIT;
    credits = Math.max(0, credits - Math.ceil(Math.max(0, fedWages - CREDIT_PHASEOUT_START[o.status]) / 1000) * 50);
    var federal = Math.max(0, bracketTax(taxable, BRACKETS[o.status]) - credits);
    var ss = SS_RATE * Math.min(ficaWages, SS_WAGE_BASE);
    var medicare = MEDICARE_RATE * ficaWages + ADDL_MEDICARE_RATE * Math.max(0, ficaWages - ADDL_MEDICARE_START);
    var state = o.state * fedWages;
    return { federal: federal, ss: ss, medicare: medicare, state: state, total: federal + ss + medicare + state };
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function fmt(x) { return money.format(Math.abs(x) < 0.005 ? 0 : x); }
  function signed(x) { return Math.abs(x) < 0.005 ? fmt(0) : (x < 0 ? '−' + fmt(-x) : '+' + fmt(x)); }
  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }

  var leftTouched = false;

  function update(e) {
    var freq = parseInt(document.getElementById('pfFreq').value, 10);
    if (!(freq > 0)) freq = 26;
    if (e && e.target && e.target.id === 'pfLeft') leftTouched = true;
    if (!leftTouched) document.getElementById('pfLeft').value = String(freq);
    var status = document.getElementById('pfStatus').value;
    if (!BRACKETS[status]) status = 'single';
    var salary = num('pfSalary'), health = num('pfHealth'), dc = num('pfDc'), left = num('pfLeft'), state = num('pfState'),
        k401Pct = num('pf401k'), premPer = num('pfPremium'), kids = num('pfKids');
    var error = document.getElementById('pfError'), msg = '';
    if ([salary, health, dc, left, state, k401Pct, premPer, kids].some(isNaN) || [salary, health, dc, premPer].some(function (v) { return v < 0; }))
      msg = 'Enter non-negative amounts in every field.';
    else if (left < 1 || left > freq || Math.round(left) !== left) msg = 'Enter a whole number of paychecks from 1 to ' + freq + ' for this pay frequency.';
    else if (state < 0 || state > 15) msg = 'Enter a state tax rate from 0 to 15%.';
    else if (k401Pct < 0 || k401Pct > 100) msg = 'Enter a 401(k) rate from 0 to 100%.';
    else if (kids < 0 || kids > 20 || Math.round(kids) !== kids) msg = 'Enter 0 to 20 children.';
    var hUsed = Math.min(health, HEALTH_FSA_LIMIT), dUsed = Math.min(dc, DC_FSA_LIMIT[status]);
    var k401 = salary * k401Pct / 100, prem = premPer * freq;
    if (!msg && k401 + prem + hUsed + dUsed > salary) msg = 'Your deductions add up to more than your salary.';
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }

    var base = { salary: salary, status: status, k401: k401, premiums: prem, kids: kids, state: state / 100 };
    base.fsa = 0; var a = taxes(base);
    base.fsa = hUsed + dUsed; var b = taxes(base);
    var fsa = hUsed + dUsed, saved = a.total - b.total;
    var perDed = fsa / left, perSaved = saved / left;
    var netWithout = (salary - k401 - prem - a.total) / freq;
    set('pfDrop', fmt(perDed - perSaved));
    set('pfPer', fmt(perDed));
    set('pfSavedPer', fmt(perSaved));
    set('pfSavedYear', fmt(saved));
    set('pfNetWithout', fmt(netWithout));
    set('pfNetWith', fmt(netWithout - perDed + perSaved));
    set('pfPerDollar', fsa > 0 ? fmt(1 - saved / fsa) : '–');
    set('pfNote', fsa > 0 ? 'Over the ' + left + ' paycheck' + (left === 1 ? '' : 's') + ' the deductions are taken, you set aside ' + fmt(fsa) +
        ' for care but your take-home pay falls by only ' + fmt(fsa - saved) + '.' : 'Enter an FSA election to see its effect.');
    var capped = [];
    if (health > HEALTH_FSA_LIMIT) capped.push('the health FSA election to the ' + TAX_YEAR + ' limit of ' + fmt(HEALTH_FSA_LIMIT));
    if (dc > DC_FSA_LIMIT[status]) capped.push('the dependent care election to the ' + TAX_YEAR + ' limit of ' + fmt(DC_FSA_LIMIT[status]));
    var capEl = document.getElementById('pfCapped');
    capEl.hidden = !capped.length;
    if (capped.length) capEl.textContent = 'The results cap ' + capped.join(' and ') + '.';
    var dcEl = document.getElementById('pfDcNote');
    dcEl.hidden = !(dUsed > 0);
    if (dUsed > 0) dcEl.textContent = 'Dependent care FSA money reduces the expenses you can count for the child and dependent care tax credit, ' +
        'and the dependent care limit is shared by both spouses. Health FSA money is use-it-or-lose-it unless your plan offers a carryover or grace period.';

    var rows = [
      ['Gross pay', salary / freq, salary / freq],
      ['401(k) / 403(b)', -k401 / freq, -k401 / freq],
      ['Pre-tax premiums', -prem / freq, -prem / freq],
      ['Health FSA', 0, -hUsed / left],
      ['Dependent care FSA', 0, -dUsed / left],
      ['Federal income tax', -a.federal / freq, -a.federal / freq + (a.federal - b.federal) / left],
      ['Social Security', -a.ss / freq, -a.ss / freq + (a.ss - b.ss) / left],
      ['Medicare', -a.medicare / freq, -a.medicare / freq + (a.medicare - b.medicare) / left],
      ['State and local tax', -a.state / freq, -a.state / freq + (a.state - b.state) / left]
    ];
    var net0 = 0, net1 = 0;
    rows.forEach(function (r) { net0 += r[1]; net1 += r[2]; });
    rows.push(['Take-home pay', net0, net1]);
    var body = document.getElementById('pfTable');
    body.textContent = '';
    rows.forEach(function (r) {
      var tr = document.createElement('tr'), th = document.createElement('th');
      th.setAttribute('scope', 'row');
      th.textContent = r[0];
      tr.appendChild(th);
      [r[1] < -0.005 ? '−' + fmt(-r[1]) : fmt(r[1]), r[2] < -0.005 ? '−' + fmt(-r[2]) : fmt(r[2]), signed(r[2] - r[1])]
        .forEach(function (v) { var td = document.createElement('td'); td.textContent = v; tr.appendChild(td); });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('pfForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
